describe("DefaultApiClient transport-failure responseHeaders", () => {
  // node-transport-failure-headers-empty-not-null: a transport-phase failure
  // produces no response headers, so the thrown ApiError must carry
  // responseHeaders === null (the documented "no headers" sentinel), not an
  // empty {} that would be indistinguishable from a real header-less response.
  it("connection failure throws NetworkError with null responseHeaders", async () => {
    const client = new DefaultApiClient();
    // Port 1 has no listener on the loopback interface; the connect attempt
    // fails before any response is received.
    let caught: ApiError | undefined;
    try {
      await client.sendRequest("GET", "http://127.0.0.1:1/never", {}, null);
    } catch (e) {
      caught = e as ApiError;
    } finally {
      await client.close();
    }
    expect(caught!.constructor).toBe(NetworkError);
    expect(caught).not.toBeInstanceOf(NetworkTimeoutError);
    expect(caught).toBeInstanceOf(ApiError);
    expect(caught!.statusCode).toBe(0);
    expect(caught!.responseHeaders).toBeNull();
    expect((caught!.cause as Error).name).toBe("TypeError");
  });

  it("an undici phase timeout throws NetworkTimeoutError", async () => {
    /* The client sets one deadline of its own, `AbortSignal.timeout`, which
     * rejects with a DOMException named TimeoutError. undici times the
     * connect, headers and body phases separately and reports each as a
     * TypeError whose cause carries a UND_ERR_*_TIMEOUT code, so the same
     * expired deadline would surface as NetworkError or NetworkTimeoutError
     * depending on which timer fired first. It is a timeout either way. */
    const originalFetch = global.fetch;
    for (const code of [
      "UND_ERR_CONNECT_TIMEOUT",
      "UND_ERR_HEADERS_TIMEOUT",
      "UND_ERR_BODY_TIMEOUT",
    ]) {
      global.fetch = (async (): Promise<Response> => {
        throw new TypeError("fetch failed", {
          cause: Object.assign(new Error("timeout"), { code }),
        });
      }) as typeof fetch;
      const client = new DefaultApiClient();
      let caught: unknown;
      try {
        await client.sendRequest("GET", "http://example.com/slow", {}, null);
      } catch (e) {
        caught = e;
      } finally {
        await client.close();
      }
      expect((caught as Error).constructor).toBe(NetworkTimeoutError);
      expect(caught).toBeInstanceOf(NetworkError);
      expect((caught as NetworkTimeoutError).statusCode).toBe(0);
    }
    global.fetch = originalFetch;
  });

  it("a request that exceeds the timeout throws NetworkTimeoutError", async () => {
    const slow = http.createServer(() => {
      /* never respond */
    });
    await new Promise<void>((resolve) => slow.listen(0, "127.0.0.1", resolve));
    const port = (slow.address() as { port: number }).port;
    const client = new DefaultApiClient(
      TransportOptions.builder().timeout(50).build(),
    );
    let caught: unknown;
    try {
      await client.sendRequest(
        "GET",
        `http://127.0.0.1:${port}/slow`,
        {},
        null,
      );
    } catch (e) {
      caught = e;
    } finally {
      await client.close();
      slow.closeAllConnections();
      await new Promise<void>((resolve) => slow.close(() => resolve()));
    }
    expect((caught as Error).constructor).toBe(NetworkTimeoutError);
    expect(caught).toBeInstanceOf(NetworkError);
    expect((caught as NetworkTimeoutError).statusCode).toBe(0);
  });

  it("using a closed client throws the invalid-state Error", async () => {
    // A wrong call order is a programming error, not an SDK error.
    const client = new DefaultApiClient();
    await client.close();
    let caught: unknown;
    try {
      await client.sendRequest("GET", `${baseUrl}/echo`, {}, null);
    } catch (e) {
      caught = e;
    }
    expect((caught as Error).constructor).toBe(Error);
    expect(caught).not.toBeInstanceOf(ZitadelError);
  });

  it("a malformed request URL throws TypeError, not NetworkError", async () => {
    const client = new DefaultApiClient();
    let caught: unknown;
    try {
      await client.sendRequest("GET", "not a url", {}, null);
    } catch (e) {
      caught = e;
    } finally {
      await client.close();
    }
    // fetch's TypeError may come from another realm, so match it by name.
    expect((caught as Error).name).toBe("TypeError");
    expect(caught).not.toBeInstanceOf(NetworkError);
    expect(caught).not.toBeInstanceOf(ZitadelError);
  });

  it("a header value with CR/LF throws TypeError, not NetworkError", async () => {
    const client = new DefaultApiClient();
    let caught: unknown;
    try {
      await client.sendRequest(
        "GET",
        `${baseUrl}/echo`,
        { "X-Bad": "a\r\nInjected: yes" },
        null,
      );
    } catch (e) {
      caught = e;
    } finally {
      await client.close();
    }
    // fetch's TypeError may come from another realm, so match it by name.
    expect((caught as Error).name).toBe("TypeError");
    expect(caught).not.toBeInstanceOf(NetworkError);
    expect(caught).not.toBeInstanceOf(ZitadelError);
  });

  it("a corrupt gzip body throws ApiError with the real status, not NetworkError", async () => {
    // The body arrives with its status and headers but the fetch layer
    // cannot decompress it: a response that could not be used.
    const client = new DefaultApiClient();
    let caught: unknown;
    try {
      await client.sendRequest("GET", `${baseUrl}/bad-gzip`, {}, null);
    } catch (e) {
      caught = e;
    } finally {
      await client.close();
    }
    expect((caught as Error).constructor).toBe(ApiError);
    expect(caught).not.toBeInstanceOf(NetworkError);
    expect((caught as ApiError).statusCode).toBe(502);
  });
});

describe("DefaultApiClient.decodeBody charset handling", () => {
  it("decodes ISO-8859-1 when declared via Content-Type charset", () => {
    const buf = Buffer.from([0xe9]);
    expect(
      DefaultApiClient.decodeBody(buf, "text/plain; charset=ISO-8859-1"),
    ).toBe("é");
  });

  it("defaults to UTF-8 when no charset is declared", () => {
    const buf = Buffer.from([0xc3, 0xa9]);
    expect(DefaultApiClient.decodeBody(buf, "text/plain")).toBe("é");
  });

  it("falls back to UTF-8 when an unknown charset is declared", () => {
    const buf = Buffer.from([0xc3, 0xa9]);
    expect(() =>
      DefaultApiClient.decodeBody(
        buf,
        "text/plain; charset=not-a-real-charset",
      ),
    ).not.toThrow();
    expect(
      DefaultApiClient.decodeBody(
        buf,
        "text/plain; charset=not-a-real-charset",
      ),
    ).toBe("é");
  });

  it("handles quoted charset values", () => {
    const buf = Buffer.from([0xe9]);
    expect(
      DefaultApiClient.decodeBody(buf, 'text/plain; charset="ISO-8859-1"'),
    ).toBe("é");
  });

  it("decodes a BOM-less utf-16 body as big-endian (RFC 2781)", () => {
    // "Log" encoded UTF-16 big-endian, no BOM: 00 4c 00 6f 00 67.
    // Node's TextDecoder maps the bare 'utf-16' label to little-endian,
    // which would mis-decode these bytes. An HTTP client resolving the
    // IANA charset UTF-16 with no BOM must default to big-endian.
    const buf = Buffer.from([0x00, 0x4c, 0x00, 0x6f, 0x00, 0x67]);
    expect(DefaultApiClient.decodeBody(buf, "text/plain; charset=utf-16")).toBe(
      "Log",
    );
    // Same bytes read little-endian would NOT be "Log" -- proves the
    // big-endian choice rather than an accidental round-trip.
    expect(new TextDecoder("utf-16le").decode(buf)).not.toBe("Log");
  });
});

describe("DefaultApiClient.buildContentDisposition multipart filename safety", () => {
  it("throws on filename containing CR/LF (header-injection attempt)", () => {
    expect(() =>
      DefaultApiClient.buildContentDisposition("file", "a\r\nX-Injected: yes"),
    ).toThrow(TypeError);
  });

  it("throws on filename containing NUL", () => {
    expect(() =>
      DefaultApiClient.buildContentDisposition(
        "file",
        `a${String.fromCharCode(0)}b.txt`,
      ),
    ).toThrow(TypeError);
  });

  it("backslash-escapes quotes and backslashes in filename", () => {
    const header = DefaultApiClient.buildContentDisposition("file", 'a"b.txt');
    expect(header).toContain('filename="a\\"b.txt"');
  });

  it("emits RFC 5987 filename* for non-ASCII filenames alongside ASCII fallback", () => {
    const header = DefaultApiClient.buildContentDisposition("file", "日本.pdf");
    expect(header).toContain("filename*=UTF-8''%E6%97%A5%E6%9C%AC.pdf");
    expect(header).toMatch(/filename="[^"]*\.pdf"/);
  });

  it("omits filename* when filename is pure ASCII", () => {
    const header = DefaultApiClient.buildContentDisposition(
      "file",
      "hello.txt",
    );
    expect(header).not.toContain("filename*=");
    expect(header).toContain('filename="hello.txt"');
  });
});

// Canonical behavior #4 — a multipart file part advertises a Content-Type
// derived from the filename extension, falling back to
// application/octet-stream when the extension is unknown.
describe("DefaultApiClient.mimeTypeForFilename (canonical behavior #4)", () => {
  it("maps .png to image/png", () => {
    expect(DefaultApiClient.mimeTypeForFilename("avatar.png")).toBe(
      "image/png",
    );
  });

  it("maps .jpg/.jpeg to image/jpeg", () => {
    expect(DefaultApiClient.mimeTypeForFilename("a.jpg")).toBe("image/jpeg");
    expect(DefaultApiClient.mimeTypeForFilename("a.jpeg")).toBe("image/jpeg");
  });

  it("falls back to application/octet-stream for an unknown extension", () => {
    expect(DefaultApiClient.mimeTypeForFilename("blob.xyzzy")).toBe(
      "application/octet-stream",
    );
  });

  it("falls back to application/octet-stream when there is no extension", () => {
    expect(DefaultApiClient.mimeTypeForFilename("noext")).toBe(
      "application/octet-stream",
    );
  });
});

// Canonical behaviors #4 and #5, end-to-end through sendRequest: the
// assembled multipart/form-data body must (a) advertise each file part's
// Content-Type from its filename extension and (b) carry a non-ASCII field
// name as raw UTF-8 bytes (never '?'-mangled or stripped). A local server
// captures the exact request bytes so the assertions check the wire form.
describe("DefaultApiClient multipart wire form (canonical behaviors #4, #5)", () => {
  function captureRawBody(): Promise<{
    url: string;
    getBody: () => Buffer;
    close: () => void;
  }> {
    return new Promise((resolve) => {
      let chunks: Buffer[] = [];
      const srv = http.createServer((req, res) => {
        chunks = [];
        req.on("data", (chunk: Buffer) => chunks.push(chunk));
        req.on("end", () => {
          res.writeHead(200, { "Content-Type": "application/json" });
          res.end('{"ok":true}');
        });
      });
      srv.listen(0, "127.0.0.1", () => {
        const addr = srv.address() as { port: number };
        resolve({
          url: `http://127.0.0.1:${addr.port}/upload`,
          getBody: () => Buffer.concat(chunks),
          close: () => srv.close(),
        });
      });
    });
  }

  it("#4 file part Content-Type is derived from the filename extension", async () => {
    const { url, getBody, close } = await captureRawBody();
    try {
      const client = new DefaultApiClient();
      // The field name doubles as the filename for Buffer parts, so the
      // extension on the field name drives the per-part Content-Type.
      await client.sendRequest(
        "POST",
        url,
        {},
        { "avatar.png": Buffer.from([0x89, 0x50, 0x4e, 0x47]) },
      );
      const body = getBody().toString("binary");
      expect(body).toContain("Content-Type: image/png");
    } finally {
      close();
    }
  });

  it("#4 unknown file extension falls back to application/octet-stream", async () => {
    const { url, getBody, close } = await captureRawBody();
    try {
      const client = new DefaultApiClient();
      await client.sendRequest(
        "POST",
        url,
        {},
        { "data.xyzzy": Buffer.from([0x00, 0x01, 0x02]) },
      );
      const body = getBody().toString("binary");
      expect(body).toContain("Content-Type: application/octet-stream");
    } finally {
      close();
    }
  });

  it("#4 raw-bytes part with no extension reuses the field name as filename and falls back to application/octet-stream", async () => {
    const { url, getBody, close } = await captureRawBody();
    try {
      const client = new DefaultApiClient();
      // Field name "file" has no extension: the field name doubles as the
      // filename and the per-part Content-Type falls back to octet-stream.
      await client.sendRequest(
        "POST",
        url,
        {},
        { file: Buffer.from([0x00, 0x01, 0x02]) },
      );
      const body = getBody().toString("binary");
      expect(body).toContain('name="file"; filename="file"');
      expect(body).toContain("Content-Type: application/octet-stream");
    } finally {
      close();
    }
  });

  it("#5 non-ASCII field name is preserved as UTF-8 in the part header", async () => {
    const { url, getBody, close } = await captureRawBody();
    try {
      const client = new DefaultApiClient();
      await client.sendRequest("POST", url, {}, { café: "crème" });
      const body = getBody();
      // The field name must appear verbatim as UTF-8 bytes — not '?'-mangled
      // (latin1 lossy encode) and not stripped.
      expect(body.toString("utf-8")).toContain('name="café"');
      const cafeUtf8 = Buffer.from("café", "utf-8");
      expect(body.includes(cafeUtf8)).toBe(true);
    } finally {
      close();
    }
  });
});

